// Copies the TypeScript types generated by ts-rs in oxframe-sdk into
// packages/protocol. In CI the published `@oxframe/protocol` is used instead;
// this keeps local cross-repo development in sync.
//
//   cargo test -p oxframe-protocol --features ts   (in ../oxframe-sdk)
//   bun run sync-protocol
import { cpSync, existsSync, readdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';

const sdk = process.env.OXFRAME_SDK_PATH ?? join(import.meta.dir, '../../oxframe-sdk');
const from = join(sdk, 'crates/oxframe-protocol/bindings');
const to = join(import.meta.dir, '../packages/protocol/src/generated');
if (!existsSync(from)) {
  console.error(
    `no bindings at ${from}; run \`cargo test -p oxframe-protocol --features ts\` in oxframe-sdk`,
  );
  process.exit(1);
}
rmSync(to, { recursive: true, force: true });
cpSync(from, to, { recursive: true });
console.log(`synced ${readdirSync(to).length} files from ${from}`);
